CREATE TABLE `bbps_refunds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` bigint unsigned NOT NULL,
  `razorpay_payment_id` varchar(100) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `status` enum('pending','processing','completed','failed','manual_review') NOT NULL DEFAULT 'pending',
  `razorpay_refund_id` varchar(100) DEFAULT NULL,
  `retry_count` int unsigned NOT NULL DEFAULT '0',
  `last_error` text,
  `last_retried_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bbps_refund_transaction` (`transaction_id`),
  KEY `idx_bbps_refund_retry` (`status`,`retry_count`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=latin1;
