--
-- Table structure for table `bbps_transactions`
--

DROP TABLE IF EXISTS `bbps_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbps_transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `operator_id` varchar(50) DEFAULT NULL,
  `utility_acc_no` varchar(50) DEFAULT NULL,
  `cycle_number` varchar(20) DEFAULT NULL,
  `confirmation_mobile_no` varchar(20) DEFAULT NULL,
  `sender_name` varchar(150) DEFAULT NULL,
  `provider_client_ref_id` varchar(64) DEFAULT NULL,
  `provider_bill_ref_id` varchar(100) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  `bbps_status` varchar(50) DEFAULT NULL,
  `bbps_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `retry_count` int DEFAULT '0',
  `max_retry` int DEFAULT '3',
  `fetch_bill` tinyint(1) DEFAULT '1',
  `bill_fetch_id` bigint unsigned DEFAULT NULL,
  `recharge_plan_id` varchar(64) DEFAULT NULL,
  `recharge_circle_id` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bbps_provider_client_ref` (`provider_client_ref_id`),
  KEY `user_id` (`user_id`),
  KEY `idx_bbps_status_retry` (`bbps_status`,`retry_count`),
  KEY `idx_bbps_bill_fetch_id` (`bill_fetch_id`),
  CONSTRAINT `bbps_transactions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `customer` (`user_id`),
  CONSTRAINT `bbps_transactions_chk_1` CHECK (json_valid(`bbps_response`))
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

