--
-- Table structure for table `category_attributes`
--

DROP TABLE IF EXISTS `category_attributes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `category_attributes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int DEFAULT NULL,
  `subcategory_id` int DEFAULT NULL,
  `attribute_key` varchar(100) NOT NULL,
  `attribute_label` varchar(150) NOT NULL,
  `input_type` enum('select','multiselect','text','number') NOT NULL,
  `is_variant` tinyint(1) DEFAULT '0',
  `is_required` tinyint(1) DEFAULT '0',
  `sort_order` int DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_active` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_category_subcategory_attr` (`category_id`,`subcategory_id`,`attribute_key`),
  KEY `category_id` (`category_id`),
  KEY `idx_subcategory_id` (`subcategory_id`)
) ENGINE=InnoDB AUTO_INCREMENT=523 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

