--
-- Table structure for table `eorder_items`
--

DROP TABLE IF EXISTS `eorder_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `eorder_items` (
  `order_item_id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `vendor_order_id` bigint NOT NULL,
  `product_id` int NOT NULL,
  `variant_id` int NOT NULL,
  `flash_sale_campaign_id` bigint DEFAULT NULL,
  `promotional_content_id` bigint unsigned DEFAULT NULL,
  `quantity` int NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reward_discount` decimal(10,2) DEFAULT '0.00',
  `reward_coins_used` int DEFAULT '0',
  `reward_earned` decimal(10,2) DEFAULT '0.00',
  `reward_coins_earned` int DEFAULT '0',
  `final_price` decimal(10,2) DEFAULT '0.00',
  `fulfillment_status` enum('active','cancellation_requested','cancelled') NOT NULL DEFAULT 'active',
  PRIMARY KEY (`order_item_id`),
  KEY `order_id` (`order_id`),
  KEY `product_id` (`product_id`),
  KEY `variant_id` (`variant_id`),
  KEY `idx_order_variant` (`order_id`,`variant_id`),
  KEY `idx_order_items_order` (`order_id`),
  KEY `idx_vendor_order` (`vendor_order_id`),
  KEY `idx_order_items_product` (`product_id`,`order_id`),
  KEY `idx_eorder_items_flash_sale` (`flash_sale_campaign_id`,`variant_id`),
  KEY `idx_eorder_items_promotional_content` (`promotional_content_id`)
) ENGINE=InnoDB AUTO_INCREMENT=264 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

