DROP TABLE IF EXISTS `eorders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `eorders` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `order_ref` varchar(50) NOT NULL,
  `user_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `address_id` int DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `status` enum('pending_payment','paid','processing','partially_shipped','shipped','delivered','rto','delivery_failed','cancelled') DEFAULT 'pending_payment',
  `expires_at` datetime DEFAULT NULL,
  `cancellation_status` enum('none','requested','approved','rejected') DEFAULT 'none',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `paid_at` datetime DEFAULT NULL,
  `product_total` decimal(10,2) DEFAULT '0.00',
  `reward_discount` decimal(10,2) DEFAULT '0.00',
  `reward_coins_used` int DEFAULT '0',
  `reward_earned` decimal(10,2) DEFAULT '0.00',
