LOCK TABLES `eproducts` WRITE;
/*!40000 ALTER TABLE `eproducts` DISABLE KEYS */;
INSERT INTO `eproducts` VALUES (1,1,2,15,74,'Sundarban Agro','Anandghana Industries','Moringa Leaves Powder ',12.00,'12119029',1,0,0,NULL,3,7,'standard','<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\"> 100% Natural &amp; Pure Moringa Powder.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\"> Rich in Vitamins, Minerals &amp; Antioxidants.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\"> Boosts Energy, Immunity &amp; Wellness.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\"> No Preservatives or Chemicals.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\"> Superfood for Smoothies, Soups &amp; Teas.</span></li></ol><p><br></p>','Sundarban Agro Moringa Powder is a 100% natural, nutrient-rich superfood made from carefully dried moringa leaves .','<p>Anandghana Industries Pvt Ltd is a top producer and supplier of high-quality dehydrated fruits, vegetables, sprouting grains, and leaves. The company maintains stringent safety and hygienic requirements while guaranteeing long shelf life, improved nutrition, and great flavor through the use of cutting-edge dehydration technology and contemporary manufacturing facilities.</p><p>The company supports rural areas and boosts their economic growth by sourcing fair prices of fresh raw ingredients directly from farmers. Every product is entirely natural, free of chemicals, preservatives, and artificial coloring, and free of bacteria.Anandghana Industries provides healthful nutrition for a healthier future with a strong dedication to purity, innovation, and wellbeing.</p>','approved',0,1,1,'','2026-01-31 06:13:34',NULL,NULL,NULL,0.0,0,'standard',0),(2,2,1,7,38,'Hammer','Hammer Lifestyle PVT LTD','Ultra Classic',18.00,'85176290',1,1,1,7,5,7,'standard','<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>2.01” Always-On Display – Large, bright screen with adjustable brightness for clear visibility in all lighting conditions.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Bluetooth Calling: For hands-free convenience, make and receive calls straight from your smartwatch.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Support for Wireless Charging: Take advantage of hassle-free, cable-free charging.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Advanced Health Monitoring: Keep tabs on your health by monitoring your blood pressure, heart rate, and SpO2 (blood oxygen).</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>In-built games, a smooth touch response for daily usage, and a raise-to-wake display are examples of smart convenience features.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Extra Interchangeable Strap: An extra strap to fit your event or style is included.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Stylish &amp; Everyday Ready: The ideal fusion of contemporary style and practicality, excellent for both everyday use and gift-giving.</li></ol>','With a large 2.01-inch Always-On Display, the HAMMER Ultra Classic Smartwatch is designed to deliver everyday convenience.','<p><strong>Hammer</strong> is a bold, youth-driven lifestyle tech brand redefining everyday gadgets with power, precision, and personality. Built for the new generation that moves fast and