--
-- Table structure for table `fitness_steps`
--

DROP TABLE IF EXISTS `fitness_steps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fitness_steps` (
  `step_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `step_date` date NOT NULL,
  `steps` int DEFAULT '0',
  `distance_km` decimal(6,2) DEFAULT '0.00',
  `calories` decimal(6,2) DEFAULT '0.00',
  `active_minutes` int DEFAULT '0',
  `source` varchar(50) DEFAULT 'health_connect',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`step_id`),
  UNIQUE KEY `unique_user_day` (`user_id`,`step_date`),
  KEY `idx_customer_steps` (`user_id`),
  KEY `idx_step_date` (`step_date`),
  KEY `idx_customer_date` (`user_id`,`step_date`),
  CONSTRAINT `fitness_steps_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `customer` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=647 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

