DROP TABLE IF EXISTS `notification_campaign_recipients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_campaign_recipients` (
  `recipient_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `campaign_id` bigint unsigned NOT NULL,
  `occurrence_no` int unsigned NOT NULL,
  `user_id` int NOT NULL,
  `language` enum('en','hi','mr') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en',
  `status` enum('pending','processing','sent','inbox_only','failed','skipped','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `skip_reason` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notification_id` int DEFAULT NULL,
  `devices_attempted` tinyint unsigned NOT NULL DEFAULT '0',
  `devices_accepted` tinyint unsigned NOT NULL DEFAULT '0',
  `image_fallback` tinyint(1) NOT NULL DEFAULT '0',
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `next_attempt_at` datetime DEFAULT NULL,
  `locked_until` datetime DEFAULT NULL,
  `lock_token` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`recipient_id`),
  UNIQUE KEY `uq_campaign_recipient` (`campaign_id`,`occurrence_no`,`user_id`),
  KEY `idx_campaign_recipients_due` (`status`,`next_attempt_at`),
  KEY `idx_campaign_recipients_lock` (`lock_token`),
  KEY `idx_campaign_recipients_campaign_status` (`campaign_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1245 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
