--
-- Table structure for table `notification_templates`
--

DROP TABLE IF EXISTS `notification_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_templates` (
  `template_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `template_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trigger_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_audience` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notification_type` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `title_en` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body_en` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_mr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body_mr` text COLLATE utf8mb4_unicode_ci,
  `title_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body_hi` text COLLATE utf8mb4_unicode_ci,
  `deep_link_pattern` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_status` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `localization_status` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `is_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` int DEFAULT NULL,
  PRIMARY KEY (`template_id`),
  UNIQUE KEY `uq_notification_template_key` (`template_key`),
  KEY `idx_notification_templates_module` (`module`),
  KEY `idx_notification_templates_enabled` (`is_enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

