  `is_ndr_active` tinyint(1) DEFAULT '0',
  `courier_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `package_count` int DEFAULT '1',
  `is_split_shipment` tinyint(1) DEFAULT '0',
