/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payments_ai` AFTER INSERT ON `payments` FOR EACH ROW BEGIN
  IF @syncing IS NULL THEN
    INSERT INTO sync_outbox (event_id, entity, operation, pk_value, payload)
    VALUES (
      UUID(), 'payments', 'insert', CAST(NEW.id AS CHAR),
      JSON_OBJECT(
        'id', NEW.id,
        'order_id', NEW.order_id,
        'payment_session_id', NEW.payment_session_id,
        'amount', CAST(NEW.amount AS CHAR),     -- keep decimals precise
        'currency', NEW.currency,
        'customer_name', NEW.customer_name,
        'customer_email', NEW.customer_email,
        'customer_phone', NEW.customer_phone,
        'payment_status', NEW.payment_status,
        'payment_method', NEW.payment_method,
        'payment_id', NEW.payment_id,
        'cf_payment_id', NEW.cf_payment_id,
        'bank_reference', NEW.bank_reference,
        'payment_time', IFNULL(DATE_FORMAT(NEW.payment_time, '%Y-%m-%d %H:%i:%s'), NULL),
        'payment_gateway', NEW.payment_gateway,
        'product_slug', NEW.product_slug,
        'webhook_data', NEW.webhook_data,       -- can be large; keep if you need it
        'created_at', DATE_FORMAT(NEW.created_at, '%Y-%m-%d %H:%i:%s'),
        'updated_at', DATE_FORMAT(NEW.updated_at, '%Y-%m-%d %H:%i:%s'),
        'extra', NEW.extra
      )
    );
  END IF;
END */;;
