INSERT INTO `privacy_policy` VALUES (1,'01','Information We Collect','We may collect personal information such as name, email address, phone number, profile information, organization details, device identifiers, IP address, transaction details, marketplace activity, and government service-related information where applicable.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(2,'02','Health & Fitness Data','On supported Android devices, RewardPlanners may collect health and fitness-related information such as step count and activity data through Google Fit, Health Connect, or supported integrations when users voluntarily grant permissions. This data may be used for wellness activities, reward calculations, fitness challenges, and engagement programs. Health data is not sold or used for advertising purposes.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(3,'03','How We Collect Data','We may collect data through user registrations, profile submissions, transactions, platform interactions, automated device logs, cookies, analytics systems, and trusted third-party integrations.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(4,'04','Purpose of Data Collection','Information may be used for account management, reward calculations, marketplace services, government document assistance, payment processing, fraud prevention, customer support, analytics, platform improvements, and legal compliance.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(5,'05','Payments & BBPS Services','RewardPlanners may provide payment-related and BBPS-related services through authorized third-party payment gateways and providers. Certain payment or BBPS-related features may still be under development and may not be available to all users.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(6,'06','Government Services Disclaimer','RewardPlanners is a private platform and is not affiliated with any government authority unless explicitly stated. Users may voluntarily upload documents for government-related assistance services where applicable.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(7,'07','Data Sharing','We do not sell personal or health-related information. Data may only be shared with authorized cloud infrastructure providers, analytics providers, payment partners, logistics providers, or legal authorities where required by law.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(8,'08','Data Security','We implement commercially reasonable security safeguards including encrypted communication, secure cloud infrastructure, restricted access controls, authentication systems, and monitoring protections.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(9,'09','Data Retention','User information may be retained only as long as necessary for platform operations, legal compliance, dispute resolution, security purposes, and contractual obligations.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(10,'10','User Rights','Users may request access, correction, deletion of personal information, withdrawal of permissions or consent, and opt out of certain communications subject to applicable laws.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(11,'11','Children’s Privacy','RewardPlanners services are intended only for users above 18 years of age unless authorized by parents, guardians, employers, or applicable organizations.',1,'2026-05-23 10:25:48','2026-05-23 10:25:48'),(12,'12','Contact Information','For privacy-related support or concerns, contact: info@rewardplanners.com',1,'2026-05-23 10:25:48','2026-05-23 10:25:48');
/*!40000 ALTER TABLE `privacy_policy` ENABLE KEYS */;
