DROP TABLE IF EXISTS `product_return_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_return_requests` (
  `request_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_item_id` int NOT NULL,
  `vendor_id` int NOT NULL,
  `user_id` int NOT NULL,
  `request_type` enum('return','replacement') NOT NULL,
  `reason` text NOT NULL,
  `video_key` varchar(512) DEFAULT NULL,
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `vendor_note` varchar(1000) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`request_id`),
  UNIQUE KEY `one_request_per_item` (`order_item_id`),
  KEY `vendor_status` (`vendor_id`,`status`),
  KEY `customer_requests` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

