INSERT INTO `products` VALUES (1,'Bike Insurance','bike-insurance','Insurance','UPTO 50% ','Ride with Confidence with the best Bike Insurance','Upto 50% off','bikeFrame.jpg','Get with Upto 50% Off','Cover your bike against riots, accident, breakdown & more.','[\"Exclusive CASH Rewards After Purchase\",\"HASSLE-FREE CLAIM ASSISTANCE\",\"PLANS FROM TOP INSURANCE COMPANIES\"]','Simply fill out the quick form above, and we\'ll help you find the perfect plan for your bike in just minutes.','active','2025-06-13 07:33:11','2025-08-22 12:53:43',' [ \n    \n{\n      \"title\": \"Product Details\",\n      \"items\": [\n        \"Third-party and Comprehensive Plans Available\",\n        \"Add-ons for Extra Protection\",\n        \"1-Year Policy with Simple Renewals\",\n        \"Digital Policy Delivered in Minutes\"\n      ]\n    },\n    {\n      \"title\": \"Standard Procedure\",\n      \"items\": [\n        \"Submit your details via the form\",\n        \"Choose your preferred policy from the options provided\",\n        \"Make the payment securely online\",\n        \"Get Cash Rewards instantly\",\n        \"Receive your policy via email instantly\",\n        \"Claim assistance available on call during emergencies\"\n      ]\n    },\n {\n      \"title\": \"What\'s Covered\",\n      \"items\": [\n        \"Accidental Damage to Your Bike\",\n        \"Theft of the Insured Bike\",\n        \"Third-party Liability\",\n        \"Fire, Flood, and Natural Disasters\" \n      ]\n    },\n{\n      \"title\": \"What’s Not Covered\",\n      \"items\": [\n        \"Regular wear and tear\",\n        \"Driving without a valid license\",\n        \"Mechanical/electrical breakdowns\",\n        \"Riding Under the Influence\"\n      ]\n    }\n  ]'),(2,'Car Insurance','car-insurance','Insurance','UPTO 75%','Drive Worry-Free with the Right Car Insurance','Upto 75% Off','carFrame.jpg','Get with Upto 75% Off','Buy your car insurance with complete support covering documentation, plan selection, and claims assistance.','[\"Exclusive CASH Rewards After Purchase\",\"HASSLE-FREE CLAIM ASSISTANCE\",\"PLANS FROM TOP INSURANCE COMPANIES\"]','Just fill out the quick form above and we’ll help you find the best plan for your car in minutes.','active','2025-06-13 07:33:24','2025-08-22 12:53:57','[\n  {\n    \"title\": \"Product Details\",\n    \"items\": [\n      \"Third-party and comprehensive plans available\",\n      \"Add-ons like zero depreciation, engine protection, and roadside assistance\",\n      \"Policy term: 1 year (renewable)\",\n      \"Digital policy issued instantly\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Submit your car and personal details via the form\",\n      \"Choose your preferred policy from the options provided\",\n      \"Make the payment securely online\",\n      \"Get Cash Rewards instantly\",\n      \"Receive your policy via email instantly\",\n      \"Claim assistance available on call during emergencies\"\n    ]\n  },\n  {\n    \"title\": \"What’s Covered\",\n    \"items\": [\n      \"Accidental damage to your car\",\n      \"Theft of the insured vehicle\",\n      \"Third-party liability (injury or property damage)\",\n      \"Fire, flood, and natural disasters\"\n    ]\n  },\n  {\n    \"title\": \"What’s Not Covered\",\n    \"items\": [\n      \"Regular wear and tear\",\n      \"Driving without a valid license\",\n      \"Mechanical/electrical breakdowns\",\n      \"Driving under the influence\"\n    ]\n  }\n]'),(3,'Health Insurance','health-insurance','Insurance','UPTO 50%','Secure Your Future with Trusted Health Insurance','Upto 50% Off','healthFrame.jpg','Get with Upto 50% Off','Covers your medical bills with cashless treatment, expert help, and plans from trusted health insurers.','[\"Exclusive CASH Rewards After Purchase\",\"HASSLE-FREE CLAIM ASSISTANCE\",\"PLANS FROM TOP INSURANCE COMPANIES\"]','Simply fill out the quick form above, and we\'ll help you find the perfect health plan for you in just minutes.','active','2025-06-13 07:37:13','2025-08-22 12:54:12','[\n  {\n    \"title\": \"Product Details\",\n    \"items\": [\n      \"Cashless Hospitalisation Across India\",\n      \"Covers Pre & Post-Hospitalisation Expenses\",\n      \"Access to a Wide Network of Trusted Hospitals\",\n      \"Tax Benefits Under Section 80D\",\n      \"Free Annual Health Check-Up (on Select Plans)\",\n      \"Lifetime Renewability on All Plans\",\n      \"No-Claim Bonus Benefits Available\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Submit your details via the form\",\n      \"Choose your preferred policy from the options provided\",\n      \"Make the payment securely online\",\n      \"Get Cash Rewards instantly\",\n      \"Receive your policy via email instantly\",\n      \"Claim assistance available on call during emergencies\"\n    ]\n  },\n  {\n    \"title\": \"What’s Covered\",\n    \"items\": [\n      \"Hospitalization Expenses\",\n      \"Critical Illness\",\n      \"Third-party Liability\",\n      \"Emergency Services\"\n    ]\n  },\n  {\n    \"title\": \"What’s Not Covered\",\n    \"items\": [\n      \"Pre-existing Conditions\",\n      \"Cosmetic Surgery\",\n      \"Self-inflicted Injuries\",\n      \"Non-medical Expenses\"\n    ]\n  }\n]'),(4,'PAN Card Assistance','pan-card-assistance','Document','Save 41%','PAN Card Application & Assistance','Save 41%','panFrame.jpg','₹1 <s>₹300</s>','Whether you need a new PAN card, want to correct existing details, or replace a lost one we’re here to make the process smooth and fast.','[\"FOR NEW PAN\",\"CORRECTION IN PAN\",\"LOST OR DAMAGED PAN\"]','Simply fill out the quick form above, and we’ll help you apply, update, or replace your PAN card with ease in just a few minutes.','active','2025-06-13 07:39:27','2025-08-28 11:10:16','[\n  {\n    \"title\": \"Types of PAN Card Services Offered\",\n    \"items\": [\n      \"New PAN Card Application\",\n      \"Correction in Existing PAN (Name, DOB, etc.)\",\n      \"Lost or Damaged PAN Card Replacement\"\n    ]\n  },\n  {\n    \"title\": \"Eligibility & Basic Document Requirements\",\n    \"items\": [\n      \"Aadhar Card or valid ID proof\",\n      \"Date of Birth proof\",\n      \"Passport-size photo (digital or physical)\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Submit your details through the enquiry form\",\n      \"Our team will contact you to understand your PAN card requirement\",\n      \"Share your documents securely via WhatsApp or email\",\n      \"Make the payment online once the process is confirmed\",\n      \"Receive updates and confirmation as your PAN application is processed\",\n      \"Support available via call for any questions or follow-up\"\n    ]\n  },\n  {\n    \"title\": \"Benefits of Applying Through Us\",\n    \"items\": [\n      \"End-to-end assistance by our support team\",\n      \"Quick and easy documentation process\",\n      \"Transparent communication and updates\",\n      \"Secure handling of personal data\"\n    ]\n  }\n]'),(5,'Aadhaar Card Assistance','aadhaar-card-assistance','Document','Save 24%','Aadhaar Card Application & Update Assistance','Save 25%','addharFrame.jpg','₹150 <s>₹200</s>','From New Enrolments to Address or Name Corrections, Our Team Ensures a Smooth and Secure Aadhaar Process.','[\"FOR NEW AADHAR CARD\",\"CORRECTION IN AADHAR CARD\",\"LOST OR DAMAGED AADHAR CARD\"]','Simply fill out the quick form above, and we\'ll guide you through your Aadhaar application, correction, or reprint process in just minutes.','active','2025-06-13 07:41:42','2025-08-22 10:54:13','[\n  {\n    \"title\": \"Types of Aadhaar Card Services Offered\",\n    \"items\": [\n      \"New Aadhaar Card Enrollment\",\n      \"Update/Correction in Existing Aadhaar (Name, DOB, Address, etc.)\",\n      \"Lost or Damaged Aadhaar Reprint Request\"\n    ]\n  },\n  {\n    \"title\": \"Eligibility & Basic Document Requirements\",\n    \"items\": [\n      \"Aadhaar Enrollment/Update Form (will be provided)\",\n      \"Identity Proof (PAN Card, Passport, Voter ID, etc.)\",\n      \"Address Proof (Bank statement, Utility bill, etc.)\",\n      \"Date of Birth Proof (Birth certificate, school certificate, etc.)\",\n      \"Passport-size photo (if required for your update)\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Submit your details through the enquiry form\",\n      \"Our team will contact you to understand your Aadhaar service requirement\",\n      \"Share your documents securely via WhatsApp or email\",\n      \"Visit your nearest Aadhaar center if biometric verification is required\",\n      \"Receive updates and confirmation as your Aadhaar request is processed\",\n      \"Support available via call for any questions or follow-up\"\n    ]\n  },\n  {\n    \"title\": \"Benefits of Applying Through Us\",\n    \"items\": [\n      \"End-to-end assistance by our support team\",\n      \"Guidance for both online and offline types\",\n      \"Clear communication and timely updates\",\n      \"Secure handling of personal documents\",\n      \"Help in form-filling and appointment booking (if needed)\"\n    ]\n  }\n]'),(6,'Passport Services','passport-services','Document','Save 12%','Passport Services Made Easy','Save 12%','passportFrame.jpg','₹2200 <s>₹2500</s>','Applying for or renewing a passport can feel complicated but we’re here to simplify the process.','[\"FOR NEW PASSPORT APPLICATION\",\"PASSPORT RENEWAL (EXPIRED OR EXPIRING SOON)\"]','Simply fill out the quick form above, and we’ll guide you through the passport application, correction, or renewal process  quickly and hassle-free.','active','2025-06-13 10:29:56','2025-08-22 12:54:56','[\n  {\n    \"title\": \"Who Can Apply Through Us?\",\n    \"items\": [\n      \"Are applying for a passport for the first time (Fresh application)\",\n      \"Want to reissue an expired passport or one with no blank pages\"\n    ]\n  },\n  {\n    \"title\": \"Eligibility & Basic Document Requirements\",\n    \"items\": [\n      \"Aadhar Card (mandatory in most cases)\",\n      \"PAN Card\",\n      \"Proof of Address (e.g. utility bill, bank statement)\",\n      \"Proof of Date of Birth (e.g. birth certificate, school certificate)\",\n      \"Old Passport (for renewals or updates)\",\n      \"Passport-sized photographs (as per govt. guidelines)\"\n    ]\n  },\n  {\n    \"title\": \"How We Help You\",\n    \"items\": [\n      \"Identify the right passport type & form\",\n      \"Help collect and verify your documents\",\n      \"Book your appointment at the nearest Passport Seva Kendra\",\n      \"Ensure error-free application submission\",\n      \"Keep you updated on progress\"\n    ]\n  },\n  {\n    \"title\": \"Why Choose Our Assistance?\",\n    \"items\": [\n      \"No confusing paperwork\",\n      \"Save time and avoid mistakes\",\n      \"Support via call, WhatsApp, or email\",\n      \"100% secure document handling\"\n    ]\n  }\n]'),(7,'Property Tax Name Change','property-tax-name-change','Property','Upto 25% Off','Property Tax Name Change Made Simple','Upto 25% Off','propertyTaxFrame.jpg','₹3000 <s>₹4000</s>','Get expert help in updating ownership details on your property tax records. Fast, reliable, and fully guided.','[\"END-TO-END GUIDANCE ON DOCUMENTATION & PROCESS\",\"DEDICATED SUPPORT UNTIL NAME CHANGE IS OFFICIALLY UPDATED\",\"HANDLED IN COORDINATION WITH LOCAL MUNICIPAL AUTHORITES\"]','Simply fill out the quick form above, and we\'ll help you find the perfect health plan for you in just minutes.','active','2025-06-13 10:31:07','2025-08-22 12:55:14','[\n  {\n    \"title\": \"Why You May Need a Name Change on Property Tax Records\",\n    \"items\": [\n      \"Sale or transfer of property\",\n      \"Inheritance after the death of the original owner\",\n      \"Name change after marriage or divorce\",\n      \"Correction of errors in the current property tax record\",\n      \"Gifting of property within family\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Fill out the enquiry form above\",\n      \"Our team will contact you to understand your reason for name change and verify basic details\",\n      \"Share the necessary documents via WhatsApp or email\",\n      \"We prepare and submit your application to the relevant municipal body\",\n      \"Track progress & receive updates until the change is successfully reflected\",\n      \"Receive confirmation copy of your updated property tax record\"\n    ]\n  },\n  {\n    \"title\": \"Documents Required\",\n    \"items\": [\n      \"Property tax receipt (latest paid bill)\",\n      \"Registered sale deed / gift deed / will / succession certificate (as applicable)\",\n      \"Identity proof of the new owner (Aadhar card, PAN card, etc.)\",\n      \"Proof of address (utility bill, ration card, etc.)\",\n      \"Affidavit or No Objection Certificate (NOC), if required by your municipality\",\n      \"Death certificate (if change is due to inheritance)\"\n    ]\n  },\n  {\n    \"title\": \"Why Apply Through Us?\",\n    \"items\": [\n      \"Expert guidance for first-timers or complex cases\",\n      \"Assistance in preparing affidavits or NOCs\",\n      \"Error-free documentation and submission\",\n      \"Tracking and follow-up with the municipal office\",\n      \"Support available via phone, WhatsApp, or email\"\n    ]\n  }\n]'),(8,'Domicile Certificate','domicile-certificate','Document','Upto 50% Off','Domicile Certificate','Upto 50% Off','domicileFrame.jpg','₹300 <s>₹400</s>','Get your Domicile Certificate with ease whether for education, employment, or legal proof of residence — we help you complete the process quickly.','[\"For New Passport Application\", \"Passport Renewal (Expired or Expiring Soon)\"]','Simply fill out the quick form above, and we’ll guide you through the domicile certificate process quickly, accurately, and with full support.','active','2025-06-13 10:32:25','2025-08-22 12:56:03','[\n  {\n    \"title\": \"Domicile Certificate Benefits\",\n    \"items\": [\n      \"Universally accepted Identity Proof\",\n      \"Valid for Lifetime\",\n      \"Applicable for Individual and Entity\",\n      \"Used in various formalities as KYC\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Just Fill Out the Simple Form Above\",\n      \"We’ll Give You a Quick Call to Understand Your Needs\",\n      \"Share Your Documents\",\n      \"Sit Back While We Handle the Application for You\",\n      \"We’ll Keep You Updated Throughout\",\n      \"Your Domicile Certificate Will Reach You Soon!\"\n    ]\n  },\n  {\n    \"title\": \"What’s Covered\",\n    \"items\": [\n      \"New Domicile Certificate Applications\",\n      \"Support for Education, Jobs & Legal Use\",\n      \"Document Verification & Guidance\",\n      \"Application Filing & Status Updates\"\n    ]\n  },\n  {\n    \"title\": \"What’s Not Covered\",\n    \"items\": [\n      \"False or Fraudulent Applications\",\n      \"Urgent or Backdated Requests\",\n      \"Cases Without Valid Residential Proof\"\n    ]\n  }\n]'),(9,'Marriage Certificate','marriage-certificate','Legal','Save 20%','Get Legally Registered with a Marriage Certificate','Save 20%','marriageFrame.jpg','₹3000 <s>₹4000</s>','From document guidance to appointment booking, we handle everything for a smooth and stress-free marriage certificate process.','[\" Recognized by Government Authorities\",\"Smooth Application Support\",\"Personalized Assistance Throughout\"]','Simply fill out the quick form above, and we\'ll help you complete your marriage certificate process with ease and expert support.','active','2025-06-13 10:33:27','2025-08-22 12:56:12','[\n  {\n    \"title\": \"Why Marriage Certificate is needed\",\n    \"items\": [\n      \"Changing surname post-marriage.\",\n      \"Applying for spouse visas or passports.\",\n      \"Adding a spouse to health insurance or financial accounts.\",\n      \"Legal recognition of your relationship.\"\n    ]\n  },\n  {\n    \"title\": \"Am I eligible to apply for a marriage certificate?\",\n    \"items\": [\n      \"You are legally married (via ceremony or court).\",\n      \"Both partners are adults (21+ for men, 18+ for women).\",\n      \"You have valid identity and age/address proof.\"\n    ]\n  },\n  {\n    \"title\": \"Documents Required\",\n    \"items\": [\n      \"Aadhar Card of both partners.\",\n      \"Marriage photo or wedding invitation card.\",\n      \"Age proof (birth certificate, school certificate, etc.).\",\n      \"Address proof (utility bill, voter ID, etc.).\",\n      \"Passport-size photos.\",\n      \"Witness ID proofs (if required)\"\n    ]\n  },\n  {\n    \"title\": \"Step-by-Step Process\",\n    \"items\": [\n      \"Contact you to understand your case.\",\n      \"Collect documents via WhatsApp/email.\",\n      \"Help fill out the correct government forms.\",\n      \"Book your appointment (if needed).\",\n      \"Share status updates and guide you till the certificate is received.\"\n    ]\n  }\n]'),(10,'Rent Agreement Registration','rent-agreement-registration','Legal','Upto 30% Off','Rent Agreement Registration','Upto 30% Off','rentFrame.jpg','₹700 <s>₹1000</s>','We handle everything from drafting and collecting documents to getting your rent agreement notarized or registered.','[\"Assistance with Drafting & Registration\",\"Legally Compliant Agreements Prepared by Experts\",\"No Confusing Paperwork, No Hidden Charges\"]','Simply fill out the quick form above, and we’ll help you complete your rent agreement smoothly with expert support every step of the way.','active','2025-06-13 10:34:26','2025-08-22 12:56:26','[\n  {\n    \"title\": \"Why is Rent Agreement important?\",\n    \"items\": [\n      \"It protects both parties legally.\",\n      \"It’s required for address proof (for Aadhar, passport, etc.).\",\n      \"Registered agreements hold more legal weight than notarized ones.\"\n    ]\n  },\n  {\n    \"title\": \"How long does it take to get the Rent Agreement?\",\n    \"items\": [\n      \"Notarized agreements: 24–48 hours.\",\n      \"Registered agreements: 3–5 working days (depends on appointment slots at the registrar).\"\n    ]\n  },\n  {\n    \"title\": \"What’s the difference between Notarized and Registered Agreements?\",\n    \"items\": [\n      \"Notarized:\\n- Suitable for up to 11 months.\\n- Quicker and cheaper.\\n- Legally valid but not mandatory.\",\n      \"Registered:\\n- Required for agreements 12 months or longer.\\n- Legally stronger, mandatory in some states like Maharashtra.\\n- Involves biometric verification and stamp duty.\"\n    ]\n  },\n  {\n    \"title\": \"Can I do this without the landlord/tenant being physically present?\",\n    \"items\": [\n      \"For notarized agreements, yes documents can be shared digitally.\",\n      \"For registered agreements, both parties usually need to be present for biometrics (unless your city allows remote/digital KYC).\"\n    ]\n  },\n  {\n    \"title\": \"Step-by-Step Process\",\n    \"items\": [\n      \"Start by Filling Out a Simple Form\",\n      \"We’ll Personally Reach Out to Understand Your Needs\",\n      \"Easily Share Your Documents – We’ll Guide You\",\n      \"Review and Approve Your Draft Agreement\",\n      \"Leave the Notarization or Registration to Us\",\n      \"Receive Your Final Agreement Without Any Hassle\",\n      \"We’re Here if You Need Any Help Later\"\n    ]\n  }\n]'),(11,'Driving License','driving-license','Legal','Upto 16% Off','Driving License Your Legal Driving Permit','Upto 16% Off','drivingLicenceFrame.jpg','Two & Four Wheeler ₹4500 <s>₹5000</s>','From application to approval, we make the process smooth for both two-wheeler and four-wheeler licenses.','[\"Two-Wheeler and Four-Wheeler Applicants\",\"Support for Learner & Permanent Licenses\",\"Step-by-Step Guidance for Every Stage\"]','Simply fill out the quick form, and we\'ll guide you through the entire process ','active','2025-06-13 10:35:40','2025-08-22 12:56:40','[\n  {\n    \"title\": \"Can You apply for both two-wheeler and four-wheeler licenses together?\",\n    \"items\": [\n      \"Yes, you can apply for a combined license covering both.\",\n      \"The process is slightly longer, as you’ll need to clear driving tests for both vehicle types.\",\n      \"Our team will help you schedule everything together to save time.\"\n    ]\n  },\n  {\n    \"title\": \"Step-by-Step Process\",\n    \"items\": [\n      \"Start by Filling Out the Quick Form\",\n      \"Our Team Will Reach Out to Understand Your Needs\",\n      \"Easily Share Your Documents With Us\",\n      \"We’ll Take Care of the Application Process\",\n      \"Visit the RTO for Your Biometric & Learner’s Test\",\n      \"We’ll Help You Book Your Final Driving Test\",\n      \"Get Your License Delivered to Your Doorstep\",\n      \"Reach Out Anytime We’re Here to Help\"\n    ]\n  },\n  {\n    \"title\": \"What’s the difference between a learner and permanent license?\",\n    \"items\": [\n      \"A learner’s license is the first step valid for 6 months.\",\n      \"After 30 days from its issue, you can apply for a permanent license.\",\n      \"You must pass a driving test to receive the permanent license.\"\n    ]\n  },\n  {\n    \"title\": \"What happens if you fail the driving test?\",\n    \"items\": [\n      \"You can reapply for the test after 7 days.\",\n      \"We’ll help you with rescheduling and guide you on improving your chances of passing.\"\n    ]\n  },\n  {\n    \"title\": \"How long does it take to get the license?\",\n    \"items\": [\n      \"Learner’s license: Usually issued within 2–3 days after application.\",\n      \"Permanent license: Issued after you pass the driving test, typically 15–30 days after the learner stage.\"\n    ]\n  }\n]'),(12,'MSEB Name Change Service','mseb-name-change','utility','Save 20%','MSEB Name Change Update Your Utility Records','Save 20%','msebFrame.jpg','₹1200 <s>₹1500</s>','End-to-end support for updating the registered name on your MSEB electricity connection, with guidance on required documents and formalities.','[\"END-TO-END APPLICATION SUPPORT\", \"EXPERT GUIDANCE AT EVERY STEP\", \"FAST & RELIABLE PROCESSING\"]','Simply fill out the quick form above, and we’ll help you update the name on your MSEB electricity connection without any hassle.','active','2025-06-14 10:39:33','2025-08-23 03:51:31','[\n  {\n    \"title\": \"Who can apply for an MSEB name change?\",\n    \"items\": [\n      \"The current property owner or legal occupant of the premises.\",\n      \"Legal heir in case of the original owner’s demise.\",\n      \"Buyer of the property where the connection exists.\"\n    ]\n  },\n  {\n    \"title\": \"Documents Required\",\n    \"items\": [\n      \"Application form (signed)\",\n      \"Copy of sale deed / property ownership proof\",\n      \"Copy of latest MSEB electricity bill\",\n      \"Photo ID of new owner (Aadhar, PAN, etc.)\",\n      \"No Objection Certificate (if applicable)\",\n      \"Death certificate and legal heir certificate (in case of succession)\"\n    ]\n  },\n  {\n    \"title\": \"How long does the name change process take?\",\n    \"items\": [\n      \"Typically 7 to 15 working days, depending on document verification and submission to the local MSEB office.\"\n    ]\n  },\n  {\n    \"title\": \"Is physical presence at the MSEB office required?\",\n    \"items\": [\n      \"In most cases, no. We assist you with the process remotely.\",\n      \"However, certain locations or cases (e.g., joint property or disputes) may require a physical visit.\"\n    ]\n  },\n  {\n    \"title\": \"Will the electricity connection be affected during the process?\",\n    \"items\": [\n      \"No, your electricity supply remains uninterrupted during the name change procedure.\"\n    ]\n  },\n  {\n    \"title\": \"Step-by-Step Process\",\n    \"items\": [\n      \"Start by Filling Out a Simple Enquiry Form\",\n      \"Our Team Will Call to Understand Your Case\",\n      \"Share Documents Securely via WhatsApp or Email\",\n      \"We’ll Prepare and Review Your Application\",\n      \"Submission Support or Handling by Our Experts\",\n      \"Receive Updates and Timely Follow-Ups\",\n      \"Receive Confirmation Once Your Name Is Updated\"\n    ]\n  }\n]'),(13,'Income Tax Return – Plan A','income-tax-return-plan-a','ITR Filing','Save 33%','File Your Income Tax Return with Confidence\'','Save 33%','itrFileFrame.jpg',NULL,'Get complete assistance for filing your income-tax return, including document collection, form preparation, expert review, and final submission.',NULL,NULL,'active','2025-06-16 07:49:43','2025-06-17 11:27:35','\n[\n  {\n    \"title\": \"What documents are needed to file ITR?\",\n    \"items\": [\n      \"PAN Card\",\n      \"Aadhaar Card\",\n      \"Bank account details\",\n      \"Form 16 (if salaried)\",\n      \"Income details (business, interest, rent, capital gains, etc.)\",\n      \"Investment proofs (for deductions under 80C, 80D, etc.)\",\n      \"Previous ITR (if applicable)\"\n    ]\n  },\n  {\n    \"title\": \"What if you miss ITR Filing deadline?\",\n    \"items\": [\n      \"You can still file a belated return, but you might face a late filing fee and interest on tax due.\",\n      \"Filing on time helps avoid notices and ensures a smoother refund process.\"\n    ]\n  },\n  {\n    \"title\": \"Can you file ITR yourself or should you take help?\",\n    \"items\": [\n      \"You can file it yourself if you\'re familiar with the process.\",\n      \"But if you\'re unsure or have multiple income sources, deductions, or capital gains, taking expert help ensures accuracy and avoids errors.\"\n    ]\n  },\n  {\n    \"title\": \"Is your data safe with us?\",\n    \"items\": [\n      \"Absolutely. We use secure systems and keep your personal and financial details confidential.\"\n    ]\n  },\n  {\n    \"title\": \"Step-by-Step Process\",\n    \"items\": [\n      \"Share Your Details with Us to Get Started\",\n      \"Our Friendly Tax Expert Will Reach Out\",\n      \"Send Your Documents Safely and Easily\",\n      \"We’ll Carefully Prepare Your ITR\",\n      \"Review and Approve with Complete Confidence\",\n      \"We File Your Return and Share the Acknowledgment\",\n      \"Count on Us for Any Help Even After Filing\"\n    ]\n  }\n]\n'),(14,'Income Tax Notice Reply','income-tax-notice-reply','Tax Services','Upto 50% Off','Income Tax Notice Reply','Upto 50% Off','taxrefundFrame.jpg','₹1000 <s>₹1500</s>','Get expert help in understanding, drafting, and submitting timely responses to any income tax notice.','[\"PERSONALISED GUIDANCE FOR EVERY NOTICE TYPE\",\"TIMELY DRAFTING AND SUBMISSION SUPPORT\",\"HANDLED BY EXPERIENCED TAX PROFESSIONALS\"]','Simply fill out the quick form above, and our experts will guide you through responding to your income tax notice clearly, correctly, and on time.','active','2025-06-16 08:02:20','2025-08-23 03:52:45','[\n  {\n    \"title\": \"Why Did You Receive an Income Tax Notice?\",\n    \"items\": [\n      \"Not filing ITR or delayed filing\",\n      \"Discrepancy in reported income vs. actual income (e.g., Form 16 vs. AIS)\",\n      \"Claiming excessive deductions\",\n      \"Mismatch in TDS details\",\n      \"Random scrutiny or verification\"\n    ]\n  },\n  {\n    \"title\": \"How Can We Help You?\",\n    \"items\": [\n      \"We\'ll review your notice and explain it in simple terms\",\n      \"Identify the exact reason and what the department expects\",\n      \"Draft a professional and compliant reply on your behalf\",\n      \"File the response correctly and on time\",\n      \"Offer ongoing support until the issue is resolved\"\n    ]\n  },\n  {\n    \"title\": \"What Do You Need to Provide?\",\n    \"items\": [\n      \"Share the notice you received (PDF or photo is fine)\",\n      \"Provide your PAN and basic details\",\n      \"Share related ITR or income documents (if asked)\"\n    ]\n  },\n  {\n    \"title\": \"What Happens If You Ignore It?\",\n    \"items\": [\n      \"Ignoring a notice may lead to penalties, reassessment, or legal action\",\n      \"Even minor delays in responding can create bigger issues\",\n      \"A proper reply ensures peace of mind and shows good compliance\"\n    ]\n  },\n  {\n    \"title\": \"Standard Procedure\",\n    \"items\": [\n      \"Share Your Income Tax Notice with Us\",\n      \"We Carefully Review and Understand the Notice\",\n      \"Our Expert Team Connects with You Promptly\",\n      \"Submit Only the Essential Documents\",\n      \"We Draft and File a Compliant Response on Your Behalf\",\n      \"Receive Filing Confirmation and Peace of Mind\"\n    ]\n  }\n]\n\n\n\n');
