/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_ai` AFTER INSERT ON `products` FOR EACH ROW BEGIN
  IF @syncing IS NULL THEN
    INSERT INTO sync_outbox (event_id, entity, operation, pk_value, payload)
    VALUES (
      UUID(), 'products', 'insert', CAST(NEW.id AS CHAR),
      JSON_OBJECT(
        'id', NEW.id,
        'name', NEW.name,
        'slug', NEW.slug,
        'category', NEW.category,
        'offer_percent', NEW.offer_percent,
        'headline', NEW.headline,
        'subheadline', NEW.subheadline,
        'hero_image', NEW.hero_image,
        'productAmt', NEW.productAmt,
        'short_description', NEW.short_description,
        'trust_labels', NEW.trust_labels,
        'disclaimer', NEW.disclaimer,
        'status', NEW.status,
        'created_at', DATE_FORMAT(NEW.created_at, '%Y-%m-%d %H:%i:%s'),
        'updated_at', DATE_FORMAT(NEW.updated_at, '%Y-%m-%d %H:%i:%s'),
        'sections', NEW.sections
      )
    );
  END IF;
END */;;
DELIMITER ;
