INSERT INTO `quiz_questions` VALUES (1,'What is the capital city of India?','[\"Mumbai\", \"New Delhi\", \"Kerala\", \"Maharashtra\"]',1,1,'india-capital'),(2,'Which planet is known as the Red Planet?','[\"Venus\", \"Jupiter\", \"Mars\", \"Saturn\"]',2,1,'red-planet'),(3,'How many sides does a triangle have?','[\"Three\", \"Four\", \"Five\", \"Six\"]',0,1,'triangle'),(4,'Which is the largest ocean in the world?','[\"Atlantic\", \"Indian\", \"Arctic\", \"Pacific\"]',3,1,'largest-ocean'),(5,'Where is the Taj Mahal situated?','[\"Delhi\", \"Mumbai\", \"Agra\", \"Gujarat\"]',2,1,'taj-mahal'),(6,'How many days are there in a week?','[\"Five\", \"Six\", \"Seven\", \"Eight\"]',2,1,'week-days'),(7,'At what temperature does water freeze in Celsius?','[\"0 degrees\", \"10 degrees\", \"50 degrees\", \"100 degrees\"]',0,1,'water-freeze'),(8,'What is the natural satellite of Earth?','[\"Mars\", \"The Sun\", \"Venus\", \"The Moon\"]',3,1,'earth-satellite');
