--
-- Table structure for table `razorpay_orders`
--

DROP TABLE IF EXISTS `razorpay_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `razorpay_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `client_id` int DEFAULT NULL,
  `order_source` enum('internal','external') DEFAULT 'internal',
  `razorpay_order_id` varchar(255) DEFAULT NULL,
  `receipt` varchar(255) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  `status` enum('created','success','failed','pending') DEFAULT 'created',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `parent_order_id` varchar(100) DEFAULT NULL,
  `razorpay_payment_id` varchar(100) DEFAULT NULL,
  `module` enum('service','bbps','ecommerce','busbooking') NOT NULL,
  `ref_id` varchar(100) DEFAULT NULL,
  `raw_response` longtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_order` (`razorpay_order_id`),
  KEY `idx_razorpay_client_id` (`client_id`),
  CONSTRAINT `fk_razorpay_orders_client` FOREIGN KEY (`client_id`) REFERENCES `api_clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=222 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

