INSERT INTO `service_sections` VALUES (1,13,'faq','Everything You Need to Know','[\n    {\n      \"question\": \"Who should file an ITR?\",\n      \"answer\": \"Anyone earning taxable income as per income tax rules.\"\n    },\n    {\n      \"question\": \"Which ITR form should I use?\",\n      \"answer\": \"It depends on your income type and source.\"\n    },\n    {\n      \"question\": \"What documents are required?\",\n      \"answer\": \"Form 16, bank statements, PAN, and investment details.\"\n    },\n    {\n      \"question\": \"What is the due date for filing ITR?\",\n      \"answer\": \"Usually 31st July, unless extended by the government.\"\n    },\n    {\n      \"question\": \"Is e-verification mandatory?\",\n      \"answer\": \"Yes, ITR must be e-verified to complete filing.\"\n    }\n  ]',1,1,'2026-03-25 09:35:24'),(2,14,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"When is property tax name change required?\",\r\n      \"answer\": \"After property purchase, transfer, or ownership change.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are needed?\",\r\n      \"answer\": \"Sale deed, latest tax receipt, ID proof, and application form.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I apply for name change online?\",\r\n      \"answer\": \"Yes, you can easily apply for an MSEB (MSEDCL) name change online through our platform, and we’ll handle the entire process for you.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 7–15 working days.\"\r\n    },\r\n    {\r\n      \"question\": \"Will property tax amount change?\",\r\n      \"answer\": \"No, only the owner’s name is updated.\"\r\n    }\r\n  ]',1,1,'2026-03-26 09:31:32'),(3,15,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Why did I receive an income tax notice?\",\r\n      \"answer\": \"Due to mismatch, missing details, or verification required by the department.\"\r\n    },\r\n    {\r\n      \"question\": \"Is it mandatory to reply to the notice?\",\r\n      \"answer\": \"Yes, timely reply is mandatory to avoid penalties.\"\r\n    },\r\n    {\r\n      \"question\": \"How can I reply to an income tax notice?\",\r\n      \"answer\": \"You can consult a tax professional like us to draft and submit a proper reply on your behalf.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are usually required?\",\r\n      \"answer\": \"ITR copy, Form 16, bank statements, and supporting proofs and other documents depending on type of request.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does it take to resolve?\",\r\n      \"answer\": \"Depends on the notice type and department review.\"\r\n    }\r\n  ]',1,1,'2026-03-26 11:09:29'),(4,16,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"When is name change needed?\",\r\n      \"answer\": \"After property purchase, transfer, or ownership change.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"Sale deed, latest bill, ID proof, and application form.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does it take?\",\r\n      \"answer\": \"Usually 7–15 working days.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I apply online?\",\r\n      \"answer\": \"Yes, simply apply through our platform, upload your details, and we’ll take care of the complete MSEB (MSEDCL) name change process for you.\"\r\n    },\r\n    {\r\n      \"question\": \"Will my meter or connection change?\",\r\n      \"answer\": \"No, only the name on the bill is updated..\"\r\n    }\r\n  ]',1,1,'2026-03-26 12:57:43'),(5,10,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Is car insurance compulsory?\",\r\n      \"answer\": \"Yes. At least third-party car insurance is legally required.\"\r\n    },\r\n    {\r\n      \"question\": \"What is covered under comprehensive car insurance?\",\r\n      \"answer\": \"Own damage, third-party liability, theft, fire, accidents, and natural disasters.\"\r\n    },\r\n    {\r\n      \"question\": \"How is car insurance premium calculated?\",\r\n      \"answer\": \"Based on car value (IDV), age, location, fuel type, claim history, and add-ons.\"\r\n    },\r\n    {\r\n      \"question\": \"What is IDV in car insurance?\",\r\n      \"answer\": \"IDV (Insured Declared Value) is the current market value of your car.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I renew my car insurance after expiry?\",\r\n      \"answer\": \"Yes, but inspection may be required if the policy has lapsed.\"\r\n    }\r\n  ]',1,1,'2026-03-27 05:38:39'),(6,11,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Is bike insurance mandatory?\",\r\n      \"answer\": \"Yes. Third-party bike insurance is mandatory by law in India.\"\r\n    },\r\n    {\r\n      \"question\": \"What does bike insurance cover?\",\r\n      \"answer\": \"It covers damages to your bike, third-party liabilities, theft, fire, and natural calamities (depending on the plan).\"\r\n    },\r\n    {\r\n      \"question\": \"Can I buy bike insurance online instantly?\",\r\n      \"answer\": \"Yes, you can buy bike insurance online instantly in just a few minutes. Share your bike details, compare the best plans, and get your policy on your WhatsApp/email immediately. We’ll help you choose the right cover and complete it fast on our platform.\"\r\n    },\r\n    {\r\n      \"question\": \"What is the difference between third-party and comprehensive insurance?\",\r\n      \"answer\": \"Third-party covers legal liabilities only. Comprehensive covers your bike + third-party risks.\"\r\n    },\r\n    {\r\n      \"question\": \"Will I lose my No Claim Bonus (NCB) if I make a claim?\",\r\n      \"answer\": \"Yes, NCB is reset if you make a claim, unless you have an NCB protection add-on.\"\r\n    }\r\n  ]',1,1,'2026-03-27 06:25:32'),(7,12,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Why do I need health insurance if I’m young and healthy?\",\r\n      \"answer\": \"Medical costs are rising. Health insurance protects your savings even if you’re healthy today.\"\r\n    },\r\n    {\r\n      \"question\": \"What does health insurance cover?\",\r\n      \"answer\": \"Hospitalization, pre & post-hospital expenses, day-care treatments, and sometimes OPD (based on plan).\"\r\n    },\r\n    {\r\n      \"question\": \"What is the waiting period in health insurance?\",\r\n      \"answer\": \"Most policies have waiting periods for pre-existing diseases and certain treatments.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I cover my family under one policy?\",\r\n      \"answer\": \"Yes, through a family floater health insurance plan.\"\r\n    },\r\n    {\r\n      \"question\": \"What is cashless hospitalization?\",\r\n      \"answer\": \"Treatment without paying upfront at network hospitals; the insurer settles the bill directly.\"\r\n    }\r\n  ]',1,1,'2026-03-27 07:21:05'),(8,2,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"What details can be updated in Aadhaar?\",\r\n      \"answer\": \"Name, address, date of birth, mobile number, and photo.\"\r\n    },\r\n    {\r\n      \"question\": \"Can Aadhaar be updated online?\",\r\n      \"answer\": \"Address update can be done online; others need Aadhaar centre visit.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"Valid ID or address proof, as per UIDAI rules.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does Aadhaar update take?\",\r\n      \"answer\": \"Usually 7–14 working days.\"\r\n    },\r\n    {\r\n      \"question\": \"Will I get an update confirmation?\",\r\n      \"answer\": \"Yes, you receive an acknowledgment and tracking number.\"\r\n    }\r\n  ]',1,1,'2026-03-27 07:50:49'),(9,1,'faq','Everything You Need to Know','[\n    {\n      \"question\": \"Who can apply for a new PAN card?\",\n      \"answer\": \"Any Indian citizen or taxpayer without a PAN.\"\n    },\n    {\n      \"question\": \"When should I apply for PAN correction?\",\n      \"answer\": \"If there is an error in name, DOB, photo, or address.\"\n    },\n    {\n      \"question\": \"What is PAN reprint used for?\",\n      \"answer\": \"To get a duplicate PAN card if it’s lost or damaged.\"\n    },\n    {\n      \"question\": \"What documents are required?\",\n      \"answer\": \"ID proof, address proof, and date of birth proof.\"\n    },\n    {\n      \"question\": \"How long does the process take?\",\n      \"answer\": \"Usually 7–10 working days.\"\n    }\n  ]',1,1,'2026-03-27 09:54:52'),(10,3,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Who can apply for a two-wheeler license?\",\r\n      \"answer\": \"Anyone aged 18+ with a valid learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"Is a learner’s license required?\",\r\n      \"answer\": \"Yes, a learner’s license is mandatory before applying for a DL.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"ID proof, address proof, age proof, and learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 2–4 weeks, subject to RTO approval.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I apply online?\",\r\n      \"answer\": \"Yes, online application with RTO visit for test is required.\"\r\n    }\r\n  ]',1,1,'2026-03-27 10:17:53'),(11,4,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Who can apply for a four-wheeler license?\",\r\n      \"answer\": \"Anyone aged 18+ with a valid learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"Is a learner’s license required?\",\r\n      \"answer\": \"Yes, a learner’s license is mandatory before applying for a DL.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"ID proof, address proof, age proof, and learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 2–4 weeks, subject to RTO approval.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I apply online?\",\r\n      \"answer\": \"Yes, online application with RTO visit for test is required.\"\r\n    }\r\n  ]',1,1,'2026-03-27 10:54:13'),(12,5,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Who can apply for 2+4 wheeler license?\",\r\n      \"answer\": \"Anyone aged 18+ with a valid learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"Is one learner’s license enough?\",\r\n      \"answer\": \"Yes, a single learner’s license can cover both 2W & 4W.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"ID proof, address proof, age proof, and learner’s license.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 2–4 weeks, subject to RTO approval.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I apply online?\",\r\n      \"answer\": \"Yes, online application with RTO test for both vehicles.\"\r\n    }\r\n  ]',1,1,'2026-03-28 04:47:55'),(13,7,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"What is a domicile certificate?\",\r\n      \"answer\": \"Proof of residence in a particular state.\"\r\n    },\r\n    {\r\n      \"question\": \"Why is it required?\",\r\n      \"answer\": \"For education, government jobs, and schemes.\"\r\n    },\r\n    {\r\n      \"question\": \"Who can apply for it?\",\r\n      \"answer\": \"Residents living in the state for a required period.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are needed?\",\r\n      \"answer\": \"Address proof, ID proof, and residence documents.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does it take?\",\r\n      \"answer\": \"Yes, in most cases as per government rules.\"\r\n    }\r\n  ]',1,1,'2026-03-28 05:01:10'),(14,6,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Who can apply for a passport?\",\r\n      \"answer\": \"Any Indian citizen with valid documents.\"\r\n    },\r\n    {\r\n      \"question\": \"What types of passport services are available?\",\r\n      \"answer\": \"New passport, renewal, reissue, and correction.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"ID proof, address proof, and date of birth proof.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 2–4 weeks, subject to police verification.\"\r\n    },\r\n    {\r\n      \"question\": \"Is police verification mandatory?\",\r\n      \"answer\": \"Yes, in most cases as per government rules.\"\r\n    }\r\n  ]',1,1,'2026-03-28 05:32:09'),(15,8,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Why is a marriage certificate required?\",\r\n      \"answer\": \"For legal proof, visa, and government records.\"\r\n    },\r\n    {\r\n      \"question\": \"Who can apply for it?\",\r\n      \"answer\": \"Married couples under applicable marriage laws.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are required?\",\r\n      \"answer\": \"ID proof, address proof, marriage proof, and photos.\"\r\n    },\r\n    {\r\n      \"question\": \"Is both partner’s presence required?\",\r\n      \"answer\": \"Yes, both partners must be present during registration.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does it take?\",\r\n      \"answer\": \"Usually 7–15 working days.\"\r\n    }\r\n  ]',1,1,'2026-03-28 07:18:47'),(16,9,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"Why is a rent agreement required?\",\r\n      \"answer\": \"For legal proof of tenancy and address verification.\"\r\n    },\r\n    {\r\n      \"question\": \"What is the usual validity period?\",\r\n      \"answer\": \"Generally 11 months.\"\r\n    },\r\n    {\r\n      \"question\": \"Is online rent agreement valid?\",\r\n      \"answer\": \"Yes, registered online agreements are legally valid.\"\r\n    },\r\n    {\r\n      \"question\": \"What documents are needed?\",\r\n      \"answer\": \"ID proof of owner and tenant, and property details.\"\r\n    },\r\n    {\r\n      \"question\": \"How long does the process take?\",\r\n      \"answer\": \"Usually 1–3 working days.\"\r\n    }\r\n  ]',1,1,'2026-03-28 07:47:00'),(17,18,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"What is a Super Top-Up health insurance plan?\",\r\n      \"answer\": \"It provides additional coverage once your base policy or deductible limit is exceeded.\"\r\n    },\r\n    {\r\n      \"question\": \"How is a Super Top-Up different from a Top-Up plan?\",\r\n      \"answer\": \"A Super Top-Up considers total medical expenses in a year, while a Top-Up applies per claim.\"\r\n    },\r\n    {\r\n      \"question\": \"Do I need a base health insurance policy?\",\r\n      \"answer\": \"Yes, a base policy or you must bear the deductible amount before the Super Top-Up kicks in.\"\r\n    },\r\n    {\r\n      \"question\": \"Is Super Top-Up insurance expensive?\",\r\n      \"answer\": \"No, it offers high coverage at a relatively low premium compared to increasing base policy cover.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I buy a Super Top-Up from a different insurer?\",\r\n      \"answer\": \"Yes, it can be purchased from a different insurer than your base health policy.\"\r\n    }\r\n  ]',1,1,'2026-03-28 09:56:14'),(18,19,'faq','Everything You Need to Know','[\r\n    {\r\n      \"question\": \"What does personal accident insurance cover?\",\r\n      \"answer\": \"It covers accidental death, permanent disability, and sometimes temporary disability.\"\r\n    },\r\n    {\r\n      \"question\": \"Does it cover natural death?\",\r\n      \"answer\": \"No, it only covers injuries or death caused by accidents.\"\r\n    },\r\n    {\r\n      \"question\": \"Will I get compensation for partial disability?\",\r\n      \"answer\": \"Yes, compensation is provided based on the extent of disability as per policy terms.\"\r\n    },\r\n    {\r\n      \"question\": \"Is hospitalization required for a claim?\",\r\n      \"answer\": \"Not always, claims can be made for disabilities even without hospitalization.\"\r\n    },\r\n    {\r\n      \"question\": \"Can I have both health and personal accident insurance?\",\r\n      \"answer\": \"Yes, both serve different purposes and can be used together for better protection.\"\r\n    }\r\n  ]',1,1,'2026-03-28 09:56:14');
