INSERT INTO `service_variant_sections` VALUES (74,1,'features',NULL,'[\r\n    \"Multiple Salary\",\r\n    \"Income from House Property\",\r\n    \"Other Income\",\r\n    \"Exempted Income\",\r\n    \"CA assisted Income Tax Filing\"\r\n  ]',0),(75,2,'features',NULL,'[\r\n  \"Multiple Salary\",\r\n  \"Income from One House property\",\r\n  \"Other Income\",\r\n  \"Exempted Income\",\r\n  \"Income earned from future options (F & O) (non-audited)\"\r\n  ]',0),(76,3,'features',NULL,'[\r\n    \"Multiple Salary\",\r\n    \"Income from House Property\",\r\n    \"Other Income\",\r\n    \"Exempted Income\",\r\n    \"Multiple Capital Gains\",\r\n    \"Gains from Lottery, Gaming or Awards\"\r\n  ]',0),(77,4,'features',NULL,'[\r\n  \"All Income of Salary + Capital Gain\",\r\n  \"Income earned from outside India\",\r\n  \"NRE / NRO Account Income\",\r\n  \"Exempted Income\",\r\n  \"Guidance on DTAA\"\r\n  ]',0),(78,1,'details',NULL,'[\r\n    \"Your ITR is filed by a Tax Expert\",\r\n    \"Accurate filing as per latest rules\",\r\n    \"Error checks before submission\",\r\n    \"On-call support during filing and even after it’s done\"\r\n  ]',0),(79,2,'details',NULL,'[\r\n    \"Your ITR is filed by a Tax Expert\",\r\n    \"Accurate filing as per latest rules\",\r\n    \"Error checks before submission\",\r\n    \"On-call support during filing and even after it’s done\"\r\n  ]',0),(80,3,'details',NULL,'[\r\n    \"Your ITR is filed by a Tax Expert\",\r\n    \"Accurate filing as per latest rules\",\r\n    \"Error checks before submission\",\r\n    \"On-call support during filing and even after it’s done\"\r\n  ]',0),(81,4,'details',NULL,'[\r\n    \"Your ITR is filed by a Tax Expert\",\r\n    \"Accurate filing as per latest rules\",\r\n    \"Error checks before submission\",\r\n    \"On-call support during filing and even after it’s done\"\r\n  ]',0),(82,1,'trust_stats',NULL,'[\r\n    \"15000+ ITRs Filed\",\r\n    \"5+ Years Experience\",\r\n    \"99% On-Time Filing\"\r\n  ]',0),(83,2,'trust_stats',NULL,'[\r\n    \"15000+ ITRs Filed\",\r\n    \"5+ Years Experience\",\r\n    \"99% On-Time Filing\"\r\n  ]',0),(84,3,'trust_stats',NULL,'[\r\n    \"15000+ ITRs Filed\",\r\n    \"5+ Years Experience\",\r\n    \"99% On-Time Filing\"\r\n  ]',0),(85,4,'trust_stats',NULL,'[\r\n    \"15000+ ITRs Filed\",\r\n    \"5+ Years Experience\",\r\n    \"99% On-Time Filing\"\r\n  ]',0),(86,1,'paragraph','100% Data Safety','[\r\n    \"Your personal info is protected and used only for your service request.\"\r\n  ]',0),(87,2,'paragraph','100% Data Safety','[\r\n    \"Your personal info is protected and used only for your service request.\"\r\n  ]',0),(88,3,'paragraph','100% Data Safety','[\r\n    \"Your personal info is protected and used only for your service request.\"\r\n  ]',0),(89,4,'paragraph','100% Data Safety','[\r\n    \"Your personal info is protected and used only for your service request.\"\r\n  ]',0),(90,1,'journey','From start to finish, here’s what happens','[\r\n    [\"You share basic details\",\"Tell us what applies to you and we’ll guide you.\"],\r\n    [\"An expert takes over\",\"A tax professional handles your filing end to end, ensuring accuracy.\"],\r\n   [ \"We keep you in the loop\",\"You’re updated at every stage, and we notify you once filing is completed.\"],\r\n   [ \"Confirmation shared\",\"Acknowledgment and filing details are sent to you.\"],\r\n    [\"Support whenever needed\",\"If there’s an issue or correction required, our team is here to help.\"]\r\n  ]',0),(91,2,'journey','From start to finish, here’s what happens','[\r\n    [\"You share basic details\",\"Tell us what applies to you and we’ll guide you.\"],\r\n    [\"An expert takes over\",\"A tax professional handles your filing end to end, ensuring accuracy.\"],\r\n   [ \"We keep you in the loop\",\"You’re updated at every stage, and we notify you once filing is completed.\"],\r\n   [ \"Confirmation shared\",\"Acknowledgment and filing details are sent to you.\"],\r\n    [\"Support