DROP TABLE IF EXISTS `service_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_variants` (
  `id` int NOT NULL AUTO_INCREMENT,
  `service_id` int NOT NULL,
  `variant_name` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `short_description` text,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `status` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `can_earn_reward` tinyint(1) NOT NULL DEFAULT '0',
  `earn_reward_type` enum('fixed','percentage') NOT NULL DEFAULT 'fixed',
  `earn_reward_value` decimal(10,2) NOT NULL DEFAULT '0.00',
  `max_earn_reward` decimal(10,2) DEFAULT NULL,
  `can_redeem_reward` tinyint(1) NOT NULL DEFAULT '0',
  `redemption_type` enum('fixed','percentage') NOT NULL DEFAULT 'fixed',
  `redemption_value` decimal(10,2) NOT NULL DEFAULT '0.00',
  `max_redemption_amount` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `service_id` (`service_id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

