INSERT INTO `terms_conditions` VALUES (1,'01','Acceptance of Terms','By accessing or using RewardPlanners, users agree to comply with these Terms & Conditions and related platform policies.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(2,'02','User Eligibility','Users must be at least 18 years old and legally capable of entering into binding agreements to use RewardPlanners services.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(3,'03','Services','RewardPlanners may provide employee engagement programs, rewards, marketplace services, BBPS-related services, wellness activities, government assistance services, and digital or physical reward fulfillment.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(4,'04','Account Security','Users are responsible for maintaining the confidentiality of account credentials, passwords, OTPs, and login information.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(5,'05','User Responsibilities','Users must provide accurate information, use the platform lawfully, avoid fraudulent activities, and comply with applicable laws and regulations.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(6,'06','Acceptable Use','Illegal activities, abuse, unauthorized access attempts, scraping, spam, malicious software, and misuse of rewards or payment systems are strictly prohibited.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(7,'07','Payments & Billing','Payments processed through third-party payment gateways, banks, or service providers are subject to respective provider policies and applicable banking regulations.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(8,'08','BBPS Services','RewardPlanners may provide BBPS-related services through authorized partners. Certain payment or BBPS-related features may still be under development and may not be available to all users.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(9,'09','Government Services Disclaimer','RewardPlanners is a private platform and is not affiliated with any government authority unless explicitly stated.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(10,'10','Rewards & Marketplace','Reward points, coins, vouchers, and promotional benefits may be subject to expiry periods, redemption conditions, seller policies, or availability limitations.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(11,'11','Intellectual Property','All platform content including branding, graphics, software, trademarks, logos, and related intellectual property remain the exclusive property of RewardPlanners or respective licensors.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(12,'12','Limitation of Liability','RewardPlanners shall not be liable for indirect, incidental, special, consequential, or punitive damages arising from platform usage, third-party services, payment failures, or service interruptions.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(13,'13','Termination','RewardPlanners reserves the right to suspend, restrict, or terminate accounts violating these Terms & Conditions, applicable laws, or platform policies.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(14,'14','Changes to Terms','RewardPlanners may update or modify these Terms & Conditions periodically. Continued use of the platform after updates constitutes acceptance of revised terms.',1,'2026-05-23 10:10:27','2026-05-23 10:10:27'),(15,'15','Contact Information','For support or legal queries, contact: info@rewardplanners.com',1,'2026-05-23 10:10:27','2026-05-23 10:10:27');
/*!40000 ALTER TABLE `terms_conditions` ENABLE KEYS */;
