--
-- Table structure for table `wa_queue`
--

DROP TABLE IF EXISTS `wa_queue`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wa_queue` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `company_id` bigint DEFAULT NULL,
  `event_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `template_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `phone_full` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `body_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `order_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `idem_key` varchar(191) COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('PENDING','PROCESSING','SENT','FAILED') COLLATE utf8mb4_general_ci DEFAULT 'PENDING',
  `retry_count` int DEFAULT '0',
  `last_error` text COLLATE utf8mb4_general_ci,
  `scheduled_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `locked_at` datetime DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `button_values` longtext COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_idem` (`idem_key`),
  KEY `idx_queue` (`status`,`scheduled_at`),
  KEY `idx_order` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5408 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

